INSERT INTO `comment` VALUES (1, 305, 1, 1, 101, 5, '旅游达人小王：麦新格精品酒店离浦东机场很近，转机首选。房间干净整洁，机场接送服务很方便。早上还有早餐供应，性价比很高！', '[]', NULL, '0', '1', 3, '2026-06-26 16:31:06', NULL, NULL, NULL, NULL, NULL, '0', '感谢您的评价！机场店主打便捷，欢迎下次再来！', '2026-06-26 16:31:06', NULL, NULL);
INSERT INTO `comment` VALUES (2, 305, 2, 4, 102, 4, '金普顿前滩酒店很时尚，设计感强。房间不大但布局合理。就是周边还在开发中，吃饭选择不多。', '[]', NULL, '0', '1', 0, '2026-06-26 16:31:06', NULL, NULL, NULL, NULL, NULL, '0', '前滩正在快速发展，周边配套会越来越好！', '2026-06-26 16:31:06', NULL, NULL);
INSERT INTO `comment` VALUES (3, 306, 1, 2, 103, 3, '出差老李：老酒店了设施有点旧，空调声音大。不过位置确实方便，离地铁站近，周边吃饭也方便。价格还算合理。', '[]', NULL, '0', '2', 2, '2026-06-26 16:31:06', 'admin', '2026-06-26 16:35:30', NULL, '后面给他们升级房型了', '2026-06-26 16:35:00', '2', '感谢您的反馈！空调问题已安排排查。', '2026-06-26 16:31:06', NULL, NULL);
INSERT INTO `comment` VALUES (4, 306, 3, 8, 104, 5, 'CitiGO欢阁酒店性价比超高！静安寺旁边，出门就是商圈。装修风格年轻时尚，房间虽小但一应俱全。前台小哥哥服务热情，推荐了很多美食。', '[\"https://images.unsplash.com/photo-1551882547-be7b2a60087d?w=400&h=300&fit=crop\"]', NULL, '0', '1', 4, '2026-06-26 16:31:06', NULL, NULL, NULL, NULL, NULL, '0', '很高兴您喜欢我们的风格！CitiGO致力于为年轻人打造高性价比的住宿体验。', '2026-06-26 16:31:06', NULL, NULL);
INSERT INTO `comment` VALUES (5, 307, 2, 5, 105, 2, '度假小红：金普顿真的让人失望。双床房的床垫太软了，睡了一晚腰疼。隔音也不好，走廊说话听得一清二楚。一千多一晚不值。', '[]', NULL, '0', '1', 3, '2026-06-26 16:31:06', NULL, NULL, NULL, '客人未提前沟通床垫问题，客房服务可提供硬床垫选择。', '2026-06-26 16:31:06', '1', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (6, 308, 1, 1, 106, 4, '商务张总：麦新格整体不错，简约实用。WiFi速度很快，商务需求都能满足。卫生间稍微小了点，早餐种类可以再丰富些。', '[]', NULL, '0', '1', 0, '2026-06-26 16:31:06', NULL, NULL, NULL, NULL, NULL, '0', '感谢建议！早餐品类我们正在丰富中。', '2026-06-26 16:31:06', NULL, NULL);
INSERT INTO `comment` VALUES (7, 309, 2, 7, 107, 5, '蜜月小周：金普顿太适合情侣了！景观房看出去夜景很美，房间设计浪漫有情调。前台还帮忙准备了蜜月布置，非常贴心。下次还来！', '[\"https://images.unsplash.com/photo-1544551763-46a013bb70d5?w=400&h=300&fit=crop\"]', NULL, '0', '1', 4, '2026-06-26 16:31:06', NULL, NULL, NULL, NULL, NULL, '0', '恭喜新婚！很高兴为您制造了浪漫回忆！', '2026-06-26 16:31:06', NULL, NULL);
INSERT INTO `comment` VALUES (8, 310, 5, 19, 108, 4, '船长五号青年酒店很有特色，航海主题装修很酷。适合年轻人，公共区域社交氛围好。床位干净，价格实惠。就是淋浴间少了点。', '[]', NULL, '0', '1', 1, '2026-06-26 16:31:06', NULL, NULL, NULL, NULL, NULL, '0', '感谢您的喜欢！淋浴间问题已在扩建中。', '2026-06-26 16:31:06', NULL, NULL);
INSERT INTO `comment` VALUES (9, 310, 3, 9, 109, 2, 'CitiGO的隔音真的差，隔壁讲话我都能听到。房间也很小，行李箱都摊不开。除了位置好真没别的优点了。', '[]', NULL, '0', '1', 3, '2026-06-26 16:31:06', NULL, NULL, NULL, '客人预订的是经济房型，面积已如实标注。', '2026-06-26 16:31:06', '1', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (10, 311, 4, 12, 110, 5, 'lyx：香格里拉老牌五星果然靠谱！豪华大床房空间很大，床品舒适。服务专业周到，早餐种类丰富到吃不过来。配套设施齐全，游泳池健身房都很棒。', '[\"https://images.unsplash.com/photo-1566073771259-6a8506099945?w=400&h=300&fit=crop\"]', NULL, '0', '1', 6, '2026-06-26 16:31:06', NULL, NULL, NULL, NULL, NULL, '0', '感谢您的认可！香格里拉品质一直在线，欢迎再次光临！', '2026-06-26 16:31:06', NULL, NULL);
INSERT INTO `comment` VALUES (11, 305, 5, 18, 111, 1, '感觉很一般', '[\"https://hotel-booking-system.oss-cn-shenzhen.aliyuncs.com/merchant/logo/2026/06/26/6b84b04293a04b85aab29141247249db.png?Expires=1783067595&OSSAccessKeyId=LTAI5t5pA6ArLKrxvHRha9Mt&Signature=0oq3Wuu%2F0sqs34DOv1YqAAdbLY0%3D\"]', NULL, '0', '2', 2, '2026-06-26 16:33:17', 'admin', '2026-06-28 16:08:05', NULL, '要求我们送小孩门口的展品，真的没办法送', '2026-06-28 16:07:24', '2', '【2026-06-28 16:07:01】很抱歉呢亲亲，您要求我们送小孩门口的展品真的没办法送', '2026-06-28 16:07:02', NULL, 'test_user1');
INSERT INTO `comment` VALUES (12, 305, 71, 484, 112, 5, '旅游达人小王：赶早班机选了希尔顿惠庭，太方便了！有免费接送机服务，房间干净整洁，早餐4点半就开始供应，赶机完全无压力。五星推荐！\n\n【追加评价】Sun Jun 28 15:31:55 CST 2026\n商家还送了小礼物，很开心\n\n【追加评价】2026年06月28日15时37分28秒\n1', '[]', NULL, '0', '1', 0, '2026-06-26 16:45:04', 'test_user1', '2026-06-28 15:37:28', NULL, NULL, NULL, '0', '感谢您的推荐！机场店主打便捷，我们一直在优化早班机旅客的体验。', '2026-06-26 16:45:04', NULL, NULL);
INSERT INTO `comment` VALUES (13, 306, 71, 485, 113, 4, '出差老李：转机住了一晚，整体满意。房间隔音不错，机场接送准时。就是周边没啥吃的，只能在酒店解决。价格合理。', '[]', NULL, '0', '1', 0, '2026-06-26 16:45:04', NULL, NULL, NULL, NULL, NULL, '0', '感谢您的反馈！酒店餐厅提供全天候餐饮服务。', '2026-06-26 16:45:04', NULL, NULL);
INSERT INTO `comment` VALUES (14, 307, 71, 486, 114, 5, '度假小红：带娃出行选了家庭套房，空间很大孩子很开心。酒店有儿童游乐区，早餐还有儿童专属区域。接送机司机很热情，帮忙提行李。', '[\"https://images.unsplash.com/photo-1566073771259-6a8506099945?w=400&h=300&fit=crop\"]', NULL, '0', '1', 0, '2026-06-26 16:45:04', NULL, NULL, NULL, NULL, NULL, '0', '很高兴小朋友喜欢！我们致力于为家庭旅客提供温馨的住宿体验。', '2026-06-26 16:45:04', NULL, NULL);
INSERT INTO `comment` VALUES (15, 305, 1, 1, 115, 5, '旅游达人小王：第二次入住麦新格了，还是一如既往的好。浦东机场接送非常准时，司机师傅态度特别好。房间宽敞明亮，早餐种类丰富。推荐给所有赶早班机的朋友！', NULL, NULL, '0', '1', 0, '2026-06-21 10:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (16, 306, 1, 1, 116, 4, '出差老李：位置确实方便，离机场近。但周边没什么商业配套，晚上想吃个饭得打车出去。房间隔音一般，能听到飞机起降的声音。不过这个价位还算可以接受。', NULL, NULL, '0', '1', 0, '2026-06-26 08:30:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (17, 307, 1, 1, 117, 5, '度假小红：太满意了！带孩子入住，前台主动给升级了家庭套房。房间里有儿童拖鞋和牙刷，孩子高兴坏了。早餐的豆浆油条很地道，下次来浦东还住这里。', NULL, NULL, '0', '1', 0, '2026-07-02 14:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (18, 308, 1, 1, 118, 3, '商务张总：中规中矩的机场酒店。入住办理速度还行，但是房间的空调温度不太稳定，半夜热醒了两次。淋浴水压偏小，洗澡不太舒服。', NULL, NULL, '0', '1', 0, '2026-06-16 20:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (19, 305, 51, 192, 119, 5, '旅游达人小王：麗枫的品质一直很稳定。薰衣草香氛让人特别放松，床品舒适度满分。长阳地铁站出来步行5分钟就到，去市区也很方便。这次住了三天，每天客房打扫都很到位。', NULL, NULL, '0', '1', 0, '2026-06-21 12:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (20, 306, 51, 192, 120, 5, '出差老李：在北京出差住过很多酒店，麗枫的性价比是最高的。房间有独立办公区，网络速度快。早餐中西结合，咖啡不错。唯一小遗憾是停车场车位有点紧张。', NULL, NULL, '0', '1', 0, '2026-06-23 09:30:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (21, 309, 51, 192, 121, 1, '蜜月小周：非常糟糕的入住体验！房间有股霉味，反映给前台说换房，结果等了半小时才有人来处理。更过分的是浴室热水忽冷忽热。一千多一晚完全是被坑了，绝对不会再来。', NULL, NULL, '0', '1', 0, '2026-05-22 18:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (22, 2, 51, 192, 122, 4, '普通用户：整体不错，服务态度好。就是周边在修路，白天有点吵。晚上很安静，睡眠质量有保证。下次还会考虑入住。', NULL, NULL, '0', '1', 0, '2026-06-27 15:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (23, 305, 101, 488, 123, 4, '旅游达人小王：设计很有格调的一家酒店，大堂的艺术装置很有品味。房间大小适中，床品品质不错。龙岗这边相对安静，适合不喜欢闹市的朋友。早餐能再丰富一些就更好了。', NULL, NULL, '0', '1', 0, '2026-06-15 16:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (24, 306, 101, 488, 124, 5, '出差老李：龙岗这边性价比最高的一家！房间干净整洁，前台效率高。健身房24小时开放，出差也能保持运动习惯。周边有大运中心，晚上散步很舒服。', NULL, NULL, '0', '1', 0, '2026-06-23 10:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (25, 308, 101, 488, 125, 4, '商务张总：来深圳见客户住这里，整体体验不错。会议室设施齐全，投影仪和音响效果都很好。中餐厅的粤菜正宗，客户很满意。就是大堂略显冷清。', NULL, NULL, '0', '1', 0, '2026-06-10 17:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (26, 305, 151, 633, 126, 4, '旅游达人小王：很有成都味道的一家酒店，装修融入了很多川蜀文化元素。房间里的熊猫玩偶很可爱。就是离市中心有点远，不过地铁直达还是很方便。', NULL, NULL, '0', '1', 0, '2026-06-18 14:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (27, 306, 151, 633, 127, 5, '出差老李：在成都出差经常住这里，前台都认识我了哈哈。服务一如既往地好，房间安静舒适。早餐有担担面和钟水饺，正宗成都味。强烈推荐！', NULL, NULL, '0', '1', 0, '2026-06-25 08:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (28, 307, 151, 633, 128, 4, '度假小红：带孩子来成都玩，酒店很贴心地准备了亲子房。熊猫主题的床单孩子超级喜欢。周边有万达广场，吃饭购物都方便。就是游泳池有点小。', NULL, NULL, '0', '1', 0, '2026-06-28 11:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (29, 305, 251, 1074, 129, 5, '旅游达人小王：全季的品质没得说！西部大道这家是新开的，设施很新。全屋智能控制，窗帘灯光语音操控很灵敏。床垫软硬适中，一觉睡到天亮。出门就是宜家荟聚，逛街超方便。', NULL, NULL, '0', '1', 0, '2026-06-13 17:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (30, 308, 251, 1074, 130, 5, '商务张总：来西安出差选全季没错。房间商务配套齐全，书桌够大，椅子也舒服。网络稳定，视频会议没有卡顿。中西式早餐选择多，服务人员热情周到。', NULL, NULL, '0', '1', 0, '2026-06-21 22:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (31, 309, 251, 1074, 131, 4, '蜜月小周：和老公来西安度蜜月住的这里。前台知道是新婚给我们准备了玫瑰花和红酒，太暖心了！房间视野好能看秦岭。唯一的不足是浴室没有浴缸只有淋浴。', NULL, NULL, '0', '1', 0, '2026-06-27 10:30:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (32, 2, 251, 1074, 132, 3, '普通用户：全季的服务标准还可以，但这次入住发现房间角落有点灰尘。插座位置不太合理，床头充电不方便。整体还不错但对全季来说还有提升空间。', NULL, NULL, '0', '1', 0, '2026-05-12 16:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (33, 307, 351, 1506, 133, 5, '度假小红：白玉兰真的超出预期！海景房视野绝了，躺在床上就能看日出。房间很大很干净，装修风格清新雅致。楼下就是海边栈道，散步特别惬意。下次带父母来还住这里！', NULL, NULL, '0', '1', 0, '2026-06-06 08:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (34, 308, 351, 1506, 134, 4, '商务张总：青岛出差入住，整体体验不错。海景会议室很加分，客户赞叹不已。房间隔音好，楼下酒吧的音乐完全听不到。就是空调制冷有点猛，不太好调节。', NULL, NULL, '0', '1', 0, '2026-06-20 15:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (35, 309, 351, 1506, 135, 5, '蜜月小周：青岛之行的完美句号！酒店帮我们安排了海鲜大餐，食材新鲜味道绝佳。房间的香薰味道很好闻，服务管家几乎是秒回微信。推荐给所有来青岛的朋友！', NULL, NULL, '0', '1', 0, '2026-04-22 19:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (36, 305, 451, 1929, 136, 4, '旅游达人小王：靠近中山路步行街，地理位置绝佳。酒店外观很有闽南特色，房间内部装修现代。步行到轮渡码头十分钟，去鼓浪屿超方便。就是电梯只有一部，高峰期要等。', NULL, NULL, '0', '1', 0, '2026-06-11 12:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (37, 307, 451, 1929, 137, 4, '度假小红：这家酒店最大的优点是位置！中山路就在楼下，各种厦门小吃吃到撑。房间能看到鹭江道的夜景，很美。房间稍小但在老城区也算正常。总体满意。', NULL, NULL, '0', '1', 0, '2026-06-24 09:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (38, 308, 551, 2355, 138, 5, '商务张总：出差顺便来敦煌旅游，这家客栈太有特色了。沙漠风格的装修，晚上在院子里看星星太浪漫了。老板很热情，推荐的莫高窟游览路线很实用。房间虽不是豪华型但很有温度。', NULL, NULL, '0', '1', 0, '2026-05-28 20:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (39, 309, 551, 2355, 139, 4, '蜜月小周：丝绸之路主题的客栈，很有文化底蕴。房间干净整洁，热水充足。老板帮忙订了沙漠露营，体验感超棒。就是隔音不太好，隔壁说话能听到。', NULL, NULL, '0', '1', 0, '2026-06-15 14:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (40, 305, 801, 3440, 140, 5, '旅游达人小王：武夷山最美的客栈没有之一！百年老宅改造，保留了古建筑的韵味又加入现代舒适设施。坐在院子里喝茶看云起云落，人生一大享受。主人泡的大红袍正宗极了。', NULL, NULL, '0', '1', 0, '2026-06-01 10:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (41, 307, 801, 3440, 141, 5, '度假小红：住在云起时就像住在一幅山水画里。清晨推开窗就是云雾缭绕的武夷山，美得像仙境。客栈的私房菜用的是当地食材，健康美味。孩子们在院子里跑得满头大汗。', NULL, NULL, '0', '1', 0, '2026-05-20 08:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (42, 305, 1001, 4326, 142, 5, '旅游达人小王：大理最美的全智能酒店！房间全语音控制，科技感十足又不会觉得冰冷。洱海景观无敌，在阳台上喝着咖啡看苍山洱海，感觉时间都慢下来了。', NULL, NULL, '0', '1', 0, '2026-06-08 16:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (43, 306, 1001, 4326, 143, 4, '出差老李：来大理出差顺便度假。智能入住很方便，刷脸就能开门。房间的智能窗帘和灯光系统很好用。就是语音助手有时候反应不太灵敏。总体很不错的体验。', NULL, NULL, '0', '1', 0, '2026-06-22 11:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (44, 309, 1001, 4326, 144, 5, '蜜月小周：大理之行的惊喜！酒店位置超好，去古城打车十分钟。房间的智能系统很好玩，躺着就能控制一切。最赞的是浴室的大落地窗，泡着澡看洱海，人生享受！', NULL, NULL, '0', '1', 0, '2026-06-19 18:00:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (45, 305, 1051, 4557, 145, 5, '出差达人张先生：云端精品酒店位置很好，就在科技园核心区域。房间装修现代简约，大床很舒适。健身房设备齐全，早餐品种丰富。前台服务热情专业，下次来深圳还会选择这里！', '[]', NULL, '0', '1', 0, '2026-06-22 10:30:00', NULL, NULL, NULL, NULL, NULL, '0', '感谢张先生的高度评价！我们位于南山科技园核心，一直致力于为商务旅客提供最舒适的入住体验，期待您的再次光临！', '2026-06-23 09:15:00', NULL, 'merchant01');
INSERT INTO `comment` VALUES (46, 306, 1051, 4558, 146, 4, '家庭出游李女士：行政双床房空间宽敞，两张床够用。就是隔壁在装修早上有点吵。整体不错，游泳池加分！', '[]', NULL, '0', '1', 0, '2026-06-23 14:20:00', NULL, NULL, NULL, NULL, NULL, '0', '感谢您的反馈！装修已进入尾声，下周即可完工。游泳池全天开放，欢迎您带着家人再次来玩！\n【2026-06-27 01:11:24】111', '2026-06-27 01:11:25', NULL, 'merchant01');
INSERT INTO `comment` VALUES (47, 308, 1051, 4560, 147, 5, '商务精英王总：总统套房确实物有所值，88平米超大空间，视野极佳。管家服务非常周到，商务会议安排在酒店会议室非常方便。深圳出差首选！', '[]', NULL, '0', '1', 0, '2026-06-03 15:00:00', NULL, NULL, NULL, NULL, NULL, '0', '感谢王总的认可！总统套房配备专属管家服务，我们很高兴为您提供了满意的商务接待体验！', '2026-06-04 09:30:00', NULL, 'merchant01');
INSERT INTO `comment` VALUES (48, 2, 1052, 4562, 148, 5, '蜜月旅行的Hannah：花间堂太美了！海景大床房阳台直接看海，日出日落尽收眼底。SPA体验非常棒，餐厅的海鲜自助晚餐新鲜可口。完美的蜜月假期！', '[]', NULL, '0', '1', 0, '2026-06-13 18:00:00', NULL, NULL, NULL, NULL, NULL, '0', '恭喜Hannah新婚快乐！花间堂全体员工祝您和爱人幸福美满，期待周年纪念日再来亚龙湾相聚！', '2026-06-14 10:00:00', NULL, 'merchant01');
INSERT INTO `comment` VALUES (49, 307, 1052, 4564, 149, 4, '带娃出行奶爸：家庭亲子房设计很贴心，有儿童专用的洗漱用品和小拖鞋。就是儿童游乐区稍小了点。酒店泳池够大，孩子玩得很开心。', '[]', NULL, '0', '1', 0, '2026-06-21 11:45:00', NULL, NULL, NULL, NULL, NULL, '0', '谢谢奶爸的宝贵建议！我们正在规划扩建儿童游乐区，预计下季度完工。欢迎再次带宝贝来玩！', '2026-06-22 08:30:00', NULL, 'merchant01');
INSERT INTO `comment` VALUES (50, 308, 1052, 4563, 150, 1, '临时取消的用户：临时有事去不了，申请退款被拒了，客服态度也一般。希望改进退款政策。', '[]', NULL, '0', '1', 0, '2026-06-06 08:00:00', NULL, NULL, NULL, '退款政策不合理，我是提前一天取消的', '2026-06-07 14:00:00', '1', '感谢您的反馈。根据平台规则，入住当日取消订单确实无法退款哦。建议下次如有变动请提前联系客服，我们会尽量协调。', '2026-06-07 16:00:00', NULL, 'merchant01');
INSERT INTO `comment` VALUES (51, 309, 1053, 4569, 151, 3, '广州出差小陈：悦居位置确实好，离珠江新城地铁站步行5分钟。但房间偏小，空调制冷不够强。价格在珠江新城这个地段算合理，性价比还行吧。', '[]', NULL, '0', '1', 0, '2026-06-17 09:30:00', NULL, NULL, NULL, NULL, NULL, '0', '感谢小陈的如实评价！我们已经安排检修所有空调设备。悦居主打经济商务，欢迎下次体验我们的商务套房，空间更大更舒适。', '2026-06-18 10:00:00', NULL, 'merchant01');
INSERT INTO `comment` VALUES (52, 307, 1053, 4570, 152, 4, '行政出差李经理：行政套房配置不错，独立办公区域很方便。就是楼下在施工白天有噪音。酒店WIFI速度很快，视频会议没问题。', '[]', NULL, '0', '1', 0, '2026-06-26 16:00:00', 'merchant01', '2026-06-27 01:11:18', NULL, '111', '2026-06-27 01:11:18', '1', '感谢李经理的评价！楼下道路施工是市政工程，我们已向相关部门反馈。很高兴WIFI和办公设施能满足您的商务需求。', '2026-06-27 09:00:00', NULL, 'merchant01');
INSERT INTO `comment` VALUES (53, 2, 1054, 4572, 153, 5, '文艺青年小雨：时光里真的太有feel了！庭院里喝茶晒太阳，太惬意了。老板人很好，推荐了很多本地人吃的美食。位置在宽窄巷子里面，出门就是景区！', '[]', NULL, '0', '1', 0, '2026-06-11 14:00:00', NULL, NULL, NULL, NULL, NULL, '0', '谢谢小雨的喜爱！时光里的初心就是让每一位客人都感受到成都的慢生活。下次来记得提前说，给你留最好的庭院房！', '2026-06-12 10:30:00', NULL, 'merchant01');
INSERT INTO `comment` VALUES (54, 308, 1054, 4573, 154, 2, '隔音不太好：阁楼双床房很有特色，但是木质结构隔音确实不太好，楼上走路听得很清楚。民宿位置绝佳，如果睡眠浅的话建议选庭院房。', '[]', NULL, '0', '1', 0, '2026-06-15 10:00:00', NULL, NULL, NULL, NULL, NULL, '0', '感谢您的诚恳建议！老房子木质结构隔音确实有待改善，我们已经在加装隔音垫。下次入住时请选择庭院大床房，会更安静。', '2026-06-16 09:00:00', NULL, 'merchant01');
INSERT INTO `comment` VALUES (55, 306, 1054, 4575, 155, 3, '家庭出游的一家四口：Loft空间够大，两个孩子很喜欢楼梯上下跑。但卫生细节有待加强，床底有点灰尘。总体性价比还不错，毕竟景区里面。', '[]', NULL, '0', '0', 0, '2026-06-06 16:30:00', NULL, NULL, NULL, NULL, NULL, '0', NULL, NULL, NULL, NULL);
INSERT INTO `comment` VALUES (56, 2, 1055, 4579, 156, 5, '厦门旅游达人阿杰：鼓浪屿最佳海景酒店没有之一！房间正对大海，躺在床上就能看日出。早餐的沙茶面和海蛎煎超正宗。服务无可挑剔，下次纪念日再来！', '[]', NULL, '0', '1', 0, '2026-06-20 08:30:00', NULL, NULL, NULL, NULL, NULL, '0', '感谢阿杰的五星好评！鼓浪屿的日出确实是无价之美。沙茶面是我们的招牌早餐，大厨是地道厦门人。期待您的下一次光临！', '2026-06-21 09:00:00', NULL, 'merchant01');
INSERT INTO `comment` VALUES (57, 312, 5, 16, 157, 4, '中规中矩吧，就是没看到船长有点可惜', '[\"https://hotel-booking-system.oss-cn-shenzhen.aliyuncs.com/merchant/logo/2026/06/28/bcf4eda62fb74276b9c392a9833783a0.jpg?Expires=1783238402&OSSAccessKeyId=LTAI5t5pA6ArLKrxvHRha9Mt&Signature=ukyPSRCIkFLeFCMxxSF%2Fd6oYLBQ%3D\",\"https://hotel-booking-system.oss-cn-shenzhen.aliyuncs.com/merchant/logo/2026/06/28/8a072fafe12b434fb1e8d66bd61e5f4a.jpg?Expires=1783238408&OSSAccessKeyId=LTAI5t5pA6ArLKrxvHRha9Mt&Signature=UnwgJNcDIoiMRSb1o%2B2uk6X66xA%3D\",\"https://hotel-booking-system.oss-cn-shenzhen.aliyuncs.com/merchant/logo/2026/06/28/bd352e85583e48cda6d39058340061d2.png?Expires=1783238413&OSSAccessKeyId=LTAI5t5pA6ArLKrxvHRha9Mt&Signature=cf7mte%2ByPi3I%2FgO4Kch2rlmjTRs%3D\"]', NULL, '0', '1', 1, '2026-06-28 16:00:16', NULL, '2026-06-28 16:00:16', NULL, NULL, NULL, '0', NULL, NULL, NULL, '3035366729@qq.com');
INSERT INTO `comment` VALUES (58, 313, 5, 18, 158, 5, '很舒服', '[\"https://hotel-booking-system.oss-cn-shenzhen.aliyuncs.com/merchant/logo/2026/06/28/d87daa68b6034a62b55bcb81cc42a0dd.png?Expires=1783238678&OSSAccessKeyId=LTAI5t5pA6ArLKrxvHRha9Mt&Signature=s%2BalbXvHeIlgSKg2akbpnTfVDAw%3D\"]', NULL, '0', '1', 1, '2026-06-28 16:04:39', NULL, '2026-06-28 16:04:39', NULL, NULL, NULL, '0', NULL, NULL, NULL, '3258809710@qq.com');
