INSERT INTO `hotel` VALUES (1, '麦新格精品酒店(上海浦东国际机场店)', '上海市浦东新区世纪大道100号', 4, 4.33, 'https://hotel-booking-system.oss-cn-shenzhen.aliyuncs.com/hotel-images/001_麦新格精品酒店(上海浦东国际机场店).jpg', '接机服务,行李寄存,健身房,游泳池,会议室,WiFi', 4, 1001, '0', '2026-06-02 00:30:57', '2026-06-28 17:22:28');
