INSERT INTO `hotel` VALUES (3, '上海静安寺南京西路CitiGO欢阁酒店', '上海市浦东新区世纪大道100号', 5, 4.80, 'https://hotel-booking-system.oss-cn-shenzhen.aliyuncs.com/hotel-images/003_上海静安寺南京西路CitiGO欢阁酒店.jpg', '停车场,游泳池,接机服务', 1, 1003, '0', '2026-06-02 00:30:57', '2026-06-28 17:22:28');
