INSERT INTO `hotel` VALUES (5, '船长五号青年酒店（上海中山公园江苏路地铁站店）', '上海市浦东新区世纪大道100号', 5, 4.80, 'https://hotel-booking-system.oss-cn-shenzhen.aliyuncs.com/hotel-images/005_船长五号青年酒店（上海中山公园江苏路地铁站店）.jpg', '餐厅,停车场,SPA,行李寄存,接机服务', 3, 1005, '0', '2026-06-02 00:30:57', '2026-06-28 17:22:28');
INSERT INTO `hotel` VALUES (6, '上海美逸濠酒店（奉贤金汇龙湖天街店）', '上海市浦东新区世纪大道100号', 4, 4.70, 'https://hotel-booking-system.oss-cn-shenzhen.aliyuncs.com/hotel-images/006_上海美逸濠酒店（奉贤金汇龙湖天街店）.jpg', '会议室,WiFi,游泳池,接机服务,商务中心,SPA,行李寄存', 1, 1006, '0', '2026-06-02 00:30:57', '2026-06-28 17:22:28');
INSERT INTO `hotel` VALUES (7, '上海外滩南京东路亚朵酒店', '上海市浦东新区世纪大道100号', 4, 4.70, 'https://hotel-booking-system.oss-cn-shenzhen.aliyuncs.com/hotel-images/007_上海外滩南京东路亚朵酒店.jpg', '健身房,游泳池,行李寄存,SPA,会议室,WiFi', 4, 1007, '0', '2026-06-02 00:30:57', '2026-06-28 17:22:28');
INSERT INTO `hotel` VALUES (8, '唯庭世纪酒店(上海静安寺淮海中路店)', '上海市浦东新区世纪大道100号', 4, 4.70, 'https://hotel-booking-system.oss-cn-shenzhen.aliyuncs.com/hotel-images/008_唯庭世纪酒店(上海静安寺淮海中路店).jpg', '餐厅,游泳池,会议室,健身房,接机服务,停车场', 1, 1008, '0', '2026-06-02 00:30:57', '2026-06-28 17:22:28');
INSERT INTO `hotel` VALUES (9, '上海东方滨江大酒店(国际会议中心)', '上海市浦东新区世纪大道100号', 4, 4.70, 'https://hotel-booking-system.oss-cn-shenzhen.aliyuncs.com/hotel-images/009_上海东方滨江大酒店(国际会议中心).jpg', '健身房,接机服务,WiFi,SPA,行李寄存,商务中心', 1, 1009, '0', '2026-06-02 00:30:57', '2026-06-28 17:22:28');
